import{_ as a,o as i,c as l,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Panel Discussion","description":"","frontmatter":{"title":"Panel Discussion","date":"2026-04-02T00:00:00.000Z","updated":"2026-04-03T00:00:00.000Z","tags":["Ceph社区","分布式存储","erasure coding","object storage","CephFS"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Panel_Discussion.md","filePath":"posts/2026/Panel_Discussion.md","lastUpdated":1780459816000}'),r={name:"posts/2026/Panel_Discussion.md"};function o(n,e,s,c,d,p){return i(),l("div",null,[...e[0]||(e[0]=[t('<h2 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h2><p>本次圆桌讨论由 Vidushi 主持，邀请了 Ceph 社区多位核心专家，涵盖 dashboard、customer engineering、object storage、RADOS、NFS/CephFS、SMB 等方向的负责人，围绕 Ceph 社区当前面临的挑战、路线图规划及用户实际痛点展开了深入交流。</p><h2 id="各方向路线图概览" tabindex="-1">各方向路线图概览 <a class="header-anchor" href="#各方向路线图概览" aria-label="Permalink to &quot;各方向路线图概览&quot;">​</a></h2><h3 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h3><p>Dashboard 方向目前重点聚焦在 object storage 相关功能的集成，包括：</p><ul><li>通知管理（notification topic management）</li><li>存储类生命周期管理（storage class lifecycle management）</li><li>SMB 管理界面</li><li>NVMe 管理支持</li></ul><p>上述功能均已在 Tentacle 版本中推进。社区鼓励用户积极试用并反馈 bug，以推动功能完善。</p><h3 id="性能与-customer-engineering" tabindex="-1">性能与 Customer Engineering <a class="header-anchor" href="#性能与-customer-engineering" aria-label="Permalink to &quot;性能与 Customer Engineering&quot;">​</a></h3><p>该团队重点关注性能 benchmarking 及售前售后支持，主要进展包括：</p><ul><li><strong>Fast EC（erasure coding）</strong>：Tentacle 版本的核心特性，目标是让 file 和 block 存储也能以 EC 作为默认选项，支持 2+2、4+2、8+3、8+4 等多种 profile，从 TCO 角度替代三副本 replication。</li><li><strong>BlueStore 压缩</strong>：支持硬件压缩（Intel QAT）和软件压缩（snappy、zlib、std），持续优化压缩性能。</li><li><strong>自动化故障排查</strong>：包括 core dump 分析、日志分析等自动化工具，计划后续 upstream。</li></ul><h3 id="object-storage-rgw" tabindex="-1">Object Storage（RGW） <a class="header-anchor" href="#object-storage-rgw" aria-label="Permalink to &quot;Object Storage（RGW）&quot;">​</a></h3><p>Matt 介绍了 RGW 方向的多项创新：</p><ul><li><strong>D4N 数据缓存</strong>：基于波士顿大学研究成果的集成式数据缓存，针对分析类工作负载提供加速，持续扩展适用场景。</li><li><strong>S3 Vectors</strong>：基于 Ceph object 与 LanceDB 融合平台的 S3 向量存储实现，原型阶段接近完成，即将发布。</li><li><strong>POSIX Driver</strong>：支持将任意文件系统后端通过 S3 接口导出，不局限于 RADOS，正在产品化。</li><li><strong>S3 over RDMA</strong>：已支持通过 NFS over RDMA 访问完整 S3 命名空间，持续扩展 RDMA 支持。</li></ul><h3 id="rados-core" tabindex="-1">RADOS Core <a class="header-anchor" href="#rados-core" aria-label="Permalink to &quot;RADOS Core&quot;">​</a></h3><p>核心存储层的路线图重点：</p><ul><li><strong>Fast EC增强</strong>：Umbrella 版本将引入 direct reads，大幅提升 EC 读性能，使 EC 对读密集型工作负载更具竞争力。</li><li><strong>EC 支持 OMAP</strong>：长期以来 EC 不支持 OMAP，该特性上线后将有望实现全 EC 的Ceph 集群。</li><li><strong>Pool 迁移</strong>：支持现有 pool 迁移到新特性，降低升级门槛。</li><li><strong>Ceph Manager健壮性</strong>：持续加固各模块，提升可见性和可扩展性。</li><li><strong>Stretch Cluster 增强</strong>：结合 EC 路线图进一步完善跨站点容灾能力。</li><li><strong>Crimson</strong>：中期目标，RGW 工作负载的 tech preview 即将落地，EC 支持已在合并中，PG splitting 也将实现。</li></ul><h3 id="nfs-cephfs" tabindex="-1">NFS / CephFS <a class="header-anchor" href="#nfs-cephfs" aria-label="Permalink to &quot;NFS / CephFS&quot;">​</a></h3><p>CephFS 和 NFS 方向新特性丰富：</p><ul><li>QoS（quality of service）</li><li>TLS 支持</li><li>增强的 failover 与 high availability</li><li>DBUS 迁移至 gRPC</li><li>Prometheus 监控大幅改进</li><li>Write delegations</li><li>Binary logging与 ring buffer dump</li><li>异步 snapshot replication（中期）</li><li>Pass file cloning 与 multi-protocol 支持（长期 killer features）</li></ul><h3 id="smb" tabindex="-1">SMB <a class="header-anchor" href="#smb" aria-label="Permalink to &quot;SMB&quot;">​</a></h3><p>SMB 作为相对较新的组件，正在快速追齐 NFS 的功能集：</p><ul><li>BY（加密）支持</li><li>磁盘加密（on-disk encryption）</li><li>多租户（multi-tenancy）增强</li><li>QoS 支持</li><li>Persistent file handles（支持特定 Microsoft 应用工作负载）</li><li>SMB over RDMA（规划中，涉及 Linux 内核集成，挑战较大）</li><li>Multi-protocol 支持：同一存储卷可同时通过 CephFS、NFS、SMB 访问</li></ul><h2 id="用户问题与社区讨论" tabindex="-1">用户问题与社区讨论 <a class="header-anchor" href="#用户问题与社区讨论" aria-label="Permalink to &quot;用户问题与社区讨论&quot;">​</a></h2><h3 id="dashboard-使用体验" tabindex="-1">Dashboard 使用体验 <a class="header-anchor" href="#dashboard-使用体验" aria-label="Permalink to &quot;Dashboard 使用体验&quot;">​</a></h3><p>现场调查显示使用 Ceph dashboard 的用户较少。一位用户反映 Pacific/Octopus 版本中 dashboard 加载 OpenStack volumes 时响应极慢，Nisam 确认新版本已将加载时间优化至 2.5 秒以内。</p><h3 id="pg-rebalancing-问题-npci-2-5-pb-集群" tabindex="-1">PG Rebalancing 问题（NPCI，2.5 PB 集群） <a class="header-anchor" href="#pg-rebalancing-问题-npci-2-5-pb-集群" aria-label="Permalink to &quot;PG Rebalancing 问题（NPCI，2.5 PB 集群）&quot;">​</a></h3><p>用户反映在维护操作（服务器故障、合规补丁）时频繁触发 PG rebalancing，影响业务 IO。</p><p><strong>社区回应：</strong></p><ul><li>服务器故障触发的属于 recovery/backfill，新版本已通过 WPQ 和 mClock 调度器大幅降低对 client IO 的影响。</li><li>扩容触发的 rebalancing 可使用社区方案（如 CERN/Digital Ocean 开发的 PG premapper，利用 up items 概念控制新 OSD 的 PG 迁移节奏）。</li><li>计划将相关脚本集成进 Ceph 源码，并加入 teuthology 测试框架，同时长期目标是让 balancer 本身对扩容等主动操作更加智能感知。</li></ul><h3 id="fast-ec-与-replicated-性能对比-500-tb-12-节点全闪集群" tabindex="-1">Fast EC 与 Replicated 性能对比（500 TB，12 节点全闪集群） <a class="header-anchor" href="#fast-ec-与-replicated-性能对比-500-tb-12-节点全闪集群" aria-label="Permalink to &quot;Fast EC 与 Replicated 性能对比（500 TB，12 节点全闪集群）&quot;">​</a></h3><p>用户询问 EC 集群何时能在性能上与 replication 竞争，以及 HDD 集群的加速方案。</p><p><strong>社区回应：</strong></p><ul><li>当前测试显示，K 值越大（如 8+3、8+4），fast EC 性能越接近甚至持平 replication；2+1 这类小 K 值收益不明显。</li><li>对于 20-30 节点规模，推荐 8+3 或 8+4 profile（最小节点数要求为 K+M+1）。</li><li>Direct reads 特性（Umbrella 版本）将显著改善 EC 读性能，是 EC 全面竞争 replication 的关键。</li><li>元数据 pool 仍建议使用 replication，数据 pool 可考虑迁移至大 K 值 EC。</li><li>Cache tiering 已 deprecated，但代码仍保留；BlueStore WAL/DB 建议放在 SD/NVMe 上，DB 空间占比已从 4% 降至 2.5%。</li><li>HDD 集群加速可参考 BlueStore 压缩优化及 D4N 缓存（RGW 场景）。</li></ul><h3 id="deduplication-支持-cisco-2-pb-500-600-osd" tabindex="-1">Deduplication 支持（Cisco，~2 PB，500-600 OSD） <a class="header-anchor" href="#deduplication-支持-cisco-2-pb-500-600-osd" aria-label="Permalink to &quot;Deduplication 支持（Cisco，~2 PB，500-600 OSD）&quot;">​</a></h3><p>用户询问 Ceph 在单站点和多站点 object 存储的 deduplication 规划。</p><p><strong>社区回应：</strong></p><ul><li>Ceph 有来自韩国科学技术院的核心 deduplication 实现，尚未产品化。</li><li>RGW 层有 Benhan 实现的完整 object-level deduplication，支持全对象去重，正在扩展对小对象（head object内嵌数据）的支持。</li><li>Gaby 正在开展更经典的部分文件去重（partial file dedup）工作。</li><li>上述功能适用于多站点全局命名空间，计划在 Umbrella 版本落地。</li><li>Tentacle 版本已支持 deduplication 效果预估（preview）。</li></ul><h3 id="rgw-多站点复制问题-22-pb-50-亿对象集群" tabindex="-1">RGW 多站点复制问题（22 PB，50 亿对象集群） <a class="header-anchor" href="#rgw-多站点复制问题-22-pb-50-亿对象集群" aria-label="Permalink to &quot;RGW 多站点复制问题（22 PB，50 亿对象集群）&quot;">​</a></h3><p>用户反映多站点 replication 偶发中断，sync status 显示 shard 卡住，目前依赖 Python 脚本通过 bi log/index log/metadata log 手动同步。</p><p><strong>社区回应：</strong></p><ul><li>Quincy 版本的多站点问题较多，Reef 版本引入了 dynamic resharding 等大量修复，建议升级。</li><li>IBM 内部已针对数亿至十亿级对象规模进行 scale testing，系统已大幅改善。</li><li>近期将发布针对已知 stuck sync 场景的修复，目标版本为 Ceph main 和 Umbrella。</li><li>Shilpa Jagannath 正在将 bucket index log 从对数时间复杂度迁移至 FIFO 技术（已用于 data log），预计带来超线性的性能提升。</li><li>Dashboard 团队已实现多站点 sync rate 和 ingest rate 的可视化监控。</li><li>Bucket index 架构改进将支持单 bucket 超过 50 亿对象，并解除单对象版本数受单 shard 限制的问题。</li></ul><h3 id="mon-全部丢失的恢复" tabindex="-1">MON 全部丢失的恢复 <a class="header-anchor" href="#mon-全部丢失的恢复" aria-label="Permalink to &quot;MON 全部丢失的恢复&quot;">​</a></h3><p>用户反映小集群（5-6 节点）因补丁操作和节点自动重启导致三个 MON 全部丢失，集群宕机。</p><p><strong>社区回应：</strong></p><ul><li>可参考 Ceph 官方文档中的 MON rebuild 流程：从各 OSD 分区提取 OSD map，通过 monmaptool 重建 store.db。</li><li>生产环境强烈建议将 MON 部署在不同机架，确保 failure domain 隔离，避免单点故障导致 quorum 丢失。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次圆桌讨论覆盖了 Ceph 社区从 dashboard、object storage、erasure coding、CephFS、NFS、SMB 到 RADOS core 的全面路线图，重点方向包括：Fast EC 性能提升与 direct reads、Crimson tech preview、多站点复制稳定性、deduplication 产品化、BlueStore 压缩优化以及 multi-protocol 访问支持。社区对大规模用户的实际痛点（PG rebalancing、多站点 sync、bucket index 扩展性）均有明确的改进计划，Umbrella 版本将是多项关键特性的集中落地版本。</p>',47)])])}const g=a(r,[["render",o]]);export{u as __pageData,g as default};
